    {
      "card_ids": ["C13"],
      "claim": "The closest analogue (CZC25146, Morgan 0.3208) showed negligible total brain/plasma AUC in mice after systemic dosing, directly supporting poor CNS access for the query's methoxy-morpholine aniline aminopyrimidine core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "A closely related aminopyrimidine with the same methoxy-morpholine aniline motif had an unbound brain/unbound plasma AUC ratio of 0.17 in rats and was classified as poor brain penetration, supporting a fail prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Structurally similar aminopyrimidine-methoxy-morpholine analogues gave Bu/Pu ratios of 0.08–0.11, indicating efflux-limited brain exposure; the query's larger size and higher polar surface area make comparable or worse exposure likely.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "GNE-7915, a moderately similar analogue, was brain penetrant with a CSF/plasma unbound ratio of 0.6 in rats, providing a contradictory positive signal; however, its lower similarity and smaller, less polar structure limit transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and most numerous transferable analogues show negligible-to-poor brain penetration, and the query's high molecular weight, high TPSA, and likely efflux liability argue against meaningful CNS access. One brain-penetrant analogue (GNE-7915) prevents high confidence, but its structural differences reduce its relevance.",
  "evidence_gaps": [
    "No direct in vivo brain/plasma or CSF data for the query molecule.",
    "No experimental efflux-transporter data (P-gp/BCRP) for the query.",
    "The positive GNE-7915 evidence shows the chemical class can be brain-penetrant, but the query's larger, more polar substituents are not directly covered."
  ],
  "new_evidence_assessment": [],
